/**
 * @event
 * @name scwin.grd_resultList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_resultList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (String(r["bzProcsNo"]) !== "SUMPART") { if (typeof scwin.loadForm === 'function') { scwin.loadForm(r["bzProcsNo"], r["prtdepoId"], r["prtdepoPrnTpCd"], r["prtdepoStrtDd"], r["prtdepoEndDd"], r["nm"], r["resdbzRegNo"], r["prtdepoObjKindCd"], r["prtdepoObjTpCd"], r["prtdepoRsnCd"], r["prtdepoRsnMngrghtTpCd"], r["prtdepoRsnFncTpCd"], r["prtdepoObjTpMiscContn"], r["prtdepoShrs"], r["miscPrtdepoStrtDd"], r["miscPrtdepoEndDd"], r["miscPrtdepoRsnCd"], r["prtWithdYn"]); } else { console.error('[sdd] 행 동작 미정의: scwin.loadForm (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.loadForm'); } return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

/**
 * @method
 * @name scwin.onChangeObjKindCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onChangeObjKindCd = function () {
    /* sdd-asis-lifecycle:begin fn_OnChangeObjKindCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let defaultitem;
    const valueItem1 = "전환우선주:1|상환우선주:2|상환전환우선주:3|기타:6";
    const valueItem2 = "전환사채:4|신주인수권부사채:5|기타:6";
    const selectCtrl = $c.util.getComponent('slc_prtdepoObjTpCd');
    const sval = $c.util.getComponent('slc_prtdepoObjKindCd').getValue();
    let i;
    for (i = selectCtrl.options.length; i >= 0; i--) {
        selectCtrl.options[i] = null;
    }
    if (sval !== "1") {
        if (sval === "2") {
            defaultitem = valueItem1.split("|");
        } else {
            defaultitem = valueItem2.split("|");
        }
        for (i = 0; i < defaultitem.length; i++) {
            eld = defaultitem[i].split(":");
            selectCtrl.options[i] = new Option(eld[0]);
            selectCtrl.options[i].value = eld[1];
        }
    } else {
        selectCtrl.options[0] = new Option("해당사항없음");
        selectCtrl.options[0].value = "";
    }
    selectCtrl.options[0].selected = true;
    scwin.onChangeObjTpCd();
    /* sdd-asis-lifecycle:end */
};


