/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param type
 * @returns
 * @hidden N
*/
scwin.register = async function (type) {
    /* sdd-asis-lifecycle:begin fn_Register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await scwin.vailidationLn(type) === false) {
        return;
    }
    if (type === 'i') {
        $c.util.getComponent("dma_RegisterReq").set("nowPage", 0);
        $c.util.getComponent("dma_RegisterReq").set("nowPage", 1);
        $c.util.getComponent("dma_RegisterReq").set("nowPage", 0);
        $c.util.getComponent("dma_RegisterReq").set("transKind", 0);
    } else {
        if (type === 'u') {
            if ($c.util.getComponent("dma_RegisterReq").get("prtdepoId") === "" || scwin.form.prtdepoId.length == 0) {
                await $c.win.alert("수정하시려면, 리스트에서 선택후 수정하세요.");
                return;
            }
            if ($c.util.getComponent("dma_RegisterReq").get("prtWithdYn") === "Y") {
                await $c.win.alert("의무보유주식의 처분에서 사용중입니다. 수정할 수 없습니다.");
                return;
            }
            $c.util.getComponent("dma_RegisterReq").set("transKind", 1);
        } else {
            if (type === 'd') {
                if ($c.util.getComponent("dma_RegisterReq").get("prtdepoId") === "" || scwin.form.prtdepoId.length == 0) {
                    await $c.win.alert("삭제하시려면, 리스트에서 선택후 삭제하세요.");
                    return;
                }
                if ($c.util.getComponent("dma_RegisterReq").get("prtWithdYn") === "Y") {
                    await $c.win.alert("의무보유주식의 처분에서 사용중입니다. 삭제할 수 없습니다.");
                    return;
                }
                $c.util.getComponent("dma_RegisterReq").set("nowPage", 1);
                $c.util.getComponent("dma_RegisterReq").set("nowPage", 0);
                $c.util.getComponent("dma_RegisterReq").set("transKind", 2);
            }
        }
    }
    scwin.form.action = '/listInvstg/listPrePrtDepo.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'listPrePrtDepoReg');
    await scwin.tx_fn_Register();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.register2
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register2 = async function () {
    /* sdd-asis-lifecycle:begin fn_Register2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const rse = await $c.win.confirm("저장한 내용이 모두 삭제 됩니다. '해당사항없음'을 하시겠습니까? ");
    if (!rse) {
        return;
    }
    for (let i = 0; i < dlt_resultList.getRowCount(); i++) {
        await $c.win.alert("의무보유주식의 처분에서 사용중입니다. 삭제할 수 없습니다.");
        return;
    }
    $c.util.getComponent("dma_RegisterReq").set("nowPage", 0);
    $c.util.getComponent("dma_RegisterReq").set("nowPage", 0);
    $c.util.getComponent("dma_RegisterReq").set("nowPage", 1);
    $c.util.getComponent("dma_RegisterReq").set("transKind", 3);
    scwin.form.action = '/listInvstg/listPrePrtDepo.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'listPrePrtDepoReg');
    await scwin.tx_fn_Register2();
    /* sdd-asis-lifecycle:end */
};


