/**
 * @method
 * @name scwin.specialWord
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.specialWord = async function () {
    /* sdd-asis-lifecycle:begin fn_specialWord — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let nm = ($c.util.getComponent("ipt_nm").getValue() || '');
    if (nm.indexOf("\\") !== -1) {
        nm = nm.replace(/\\/g, "");
        $c.util.getComponent("ipt_nm").setValue(nm);
        await $c.win.alert("\\는 입력할 수 없습니다");
    }
    if (nm.indexOf("\"") !== -1) {
        nm = nm.replace(/"/g, "");
	$c.util.getComponent("ipt_nm").setValue(nm);
	await $c.win.alert("\"는 입력할 수 없습니다");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.exceptWord
 * @author Inswave
 * @date 2026. 09. 29
 * @param
