scwin.exceptWord = async function () {
    /* sdd-asis-lifecycle:begin fn_exceptWord — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let resdbzRegNo = $c.util.getComponent('ipt_resdbzRegNo').getValue();
    if (resdbzRegNo.indexOf("\'") !== -1) {
        resdbzRegNo = resdbzRegNo.replace(/'/g, "");
	$c.util.getComponent('ipt_resdbzRegNo').setValue(resdbzRegNo);
	await $c.win.alert("'는 입력할 수 없습니다");
}
/* sdd-asis-lifecycle:end */
